<script setup lang="ts">
import {computed,ref} from 'vue';
import {readingWords,deleteReadingWord,saveReadingWord,downloadJson} from './storage';
import type {ReadingWord} from './model';
const emit=defineEmits<{practice:[];reading:[string]}>();const search=ref('');const editing=ref<ReadingWord>();const meaning=ref('');
const filtered=computed(()=>readingWords.value.filter(w=>`${w.word} ${w.meaning} ${w.sourceTitle}`.toLowerCase().includes(search.value.toLowerCase())));
function edit(word:ReadingWord){editing.value=word;meaning.value=word.meaning;}
function save(){if(editing.value&&meaning.value.trim()&&saveReadingWord({...editing.value,meaning:meaning.value.trim()}))editing.value=undefined;}
function remove(word:string){if(window.confirm(`从阅读生词库移除“${word}”？单词学习记录会保留。`))deleteReadingWord(word);}
</script>
<template><section class="rp-panel"><header class="rp-row rp-wrap"><div><span class="rp-eyebrow">COLLECTED WHILE READING</span><h1>把遇见的生词，变成熟悉的词。</h1><p class="rp-muted">{{readingWords.length}} 个阅读生词，保留原文语境和文章来源。</p></div><div class="rp-row rp-wrap"><button class="rp-button secondary" :disabled="!readingWords.length" @click="downloadJson('reading-vocabulary.json',readingWords)">导出生词</button><button class="rp-button" :disabled="!readingWords.length" @click="emit('practice')">练习这些生词 →</button></div></header><label class="rp-field rp-record-search">搜索生词<input v-model="search" type="search" placeholder="单词、含义或来源文章"></label><div class="rp-word-grid"><article v-for="word in filtered" :key="word.word" class="rp-word-card"><div class="rp-row"><h2>{{word.word}}</h2><button class="rp-link" @click="edit(word)">编辑释义</button></div><p class="rp-caption">{{word.phonetic}}</p><p>{{word.meaning}}</p><blockquote v-if="word.example" class="rp-quote">{{word.example}}</blockquote><button class="rp-link rp-word-source" @click="emit('reading',word.examId)">来源：{{word.sourceTitle}} ↗</button><button class="rp-link danger" @click="remove(word.word)">移除</button></article></div><p v-if="!filtered.length" class="rp-empty">{{readingWords.length?'没有匹配的生词。':'阅读时选中文章或题目中的英文单词，点击“加入生词库”。'}}</p><div v-if="editing" class="rp-modal-backdrop" @click.self="editing=undefined"><form class="rp-dialog" role="dialog" aria-modal="true" aria-labelledby="edit-word-title" @submit.prevent="save"><h2 id="edit-word-title">编辑 {{editing.word}}</h2><label class="rp-field">释义<input v-model="meaning" required maxlength="500"></label><div class="rp-row rp-actions"><button class="rp-button secondary" type="button" @click="editing=undefined">取消</button><button class="rp-button" type="submit">保存</button></div></form></div></section></template>
